import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.Arrays;

public class MistSpan {
    static final int ALIGN = 32;
    static final int ROW = 48;
    static final byte[] MAGIC = new byte[] {'P','N','0','1'};

    public static byte[] tint_k(Path silo, byte[] wanted) throws Exception {
        if (wanted == null || wanted.length != 16) return new byte[0];
        byte[] pins = read(silo.resolve("pin.bin"));
        byte[] blob = read(silo.resolve("blob.bin"));
        for (int i = 0; i + ROW <= pins.length; i += ROW) {
            byte[] row = Arrays.copyOfRange(pins, i, i + ROW);
            ByteBuffer bb = ByteBuffer.wrap(row);
            byte[] magic = new byte[4]; bb.get(magic);
            long off = bb.getLong();
            int len = bb.getInt();
            int crc = bb.getInt();
            byte[] id = new byte[16]; bb.get(id);
            if (Arrays.equals(id, wanted)) {
                return payload(blob, magic, off, len, crc, id, row);
            }
        }
        return new byte[0];
    }

    static byte[] validateRow(byte[] blob, byte[] row) throws Exception {
        if (row.length != ROW) return null;
        ByteBuffer bb = ByteBuffer.wrap(row);
        byte[] magic = new byte[4]; bb.get(magic);
        long off = bb.getLong();
        int len = bb.getInt();
        int crc = bb.getInt();
        byte[] id = new byte[16]; bb.get(id);
        return payload(blob, magic, off, len, crc, id, row);
    }

    private static byte[] payload(byte[] blob, byte[] magic, long off, int len,
                                  int crc, byte[] id, byte[] row) throws Exception {
        if (!Arrays.equals(magic, MAGIC) || off < 0 || (off % ALIGN) != 0 || len < 0) return null;
        for (int i = 36; i < ROW; i++) if (row[i] != 0) return null;
        long raw = 4L + len;
        long take = raw + ((ALIGN - (raw % ALIGN)) % ALIGN);
        if (off > blob.length || take > blob.length - off || off > Integer.MAX_VALUE) return null;
        int pos = (int)off;
        if (ByteBuffer.wrap(blob, pos, 4).getInt() != len) return null;
        byte[] body = Arrays.copyOfRange(blob, pos + 4, pos + 4 + len);
        if (Crc.of(body) != crc) return null;
        for (int i = pos + 4 + len; i < pos + (int)take; i++) if (blob[i] != 0) return null;
        byte[] digest = MessageDigest.getInstance("SHA-256").digest(body);
        if (!Arrays.equals(id, Arrays.copyOf(digest, 16))) return null;
        return body;
    }

    private static byte[] read(Path p) throws Exception {
        return Files.exists(p) ? Files.readAllBytes(p) : new byte[0];
    }
}
